const mediaTypes=new Map([['image/jpeg','jpg'],['image/png','png'],['image/webp','webp'],['audio/mpeg','mp3'],['audio/wav','wav'],['audio/ogg','ogg'],['video/mp4','mp4'],['video/webm','webm']]);
const mediaCategories=new Set(['Logo','Product photo','Promotion','Video','Audio','Website banner','Other']);
function validMediaBytes(type,b){if(!Buffer.isBuffer(b)||!mediaTypes.has(type))return false;if(type==='image/jpeg')return b.length>3&&b[0]===0xff&&b[1]===0xd8&&b[2]===0xff;if(type==='image/png')return b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));if(type==='image/webp')return b.length>12&&b.toString('ascii',0,4)==='RIFF'&&b.toString('ascii',8,12)==='WEBP';if(type==='audio/wav')return b.length>12&&b.toString('ascii',0,4)==='RIFF'&&b.toString('ascii',8,12)==='WAVE';if(type==='audio/ogg')return b.toString('ascii',0,4)==='OggS';if(type==='audio/mpeg')return b.toString('ascii',0,3)==='ID3'||(b.length>1&&b[0]===0xff&&(b[1]&0xe0)===0xe0);if(type==='video/mp4')return b.length>12&&b.toString('ascii',4,8)==='ftyp';if(type==='video/webm')return b.subarray(0,4).equals(Buffer.from([0x1a,0x45,0xdf,0xa3]));return false}
async function hashSecret(value){ const salt=randomBytes(16).toString('hex'); const hash=await pbkdf2(value,salt,PBKDF2_ROUNDS,32,'sha256'); return {salt,hash:hash.toString('hex')}; }
async function verifySecret(value,salt,expected){if(!salt||!expected)return false;const got=await pbkdf2(value,salt,PBKDF2_ROUNDS,32,'sha256');return safeEqual(got.toString('hex'),expected);}
const dummyLoginCredential=await hashSecret(randomBytes(32).toString('hex'));
function encryptField(value){const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',fieldKey,iv),data=Buffer.concat([cipher.update(value,'utf8'),cipher.final()]);return {enc:data.toString('base64'),iv:iv.toString('base64'),tag:cipher.getAuthTag().toString('base64')};}
function decryptField(row){if(!row.salary_upi_enc)return '';const d=createDecipheriv('aes-256-gcm',fieldKey,Buffer.from(row.salary_upi_iv,'base64'));d.setAuthTag(Buffer.from(row.salary_upi_tag,'base64'));return Buffer.concat([d.update(Buffer.from(row.salary_upi_enc,'base64')),d.final()]).toString('utf8');}
function recordAudit(actor,action,subject='',detail=''){database.prepare('INSERT INTO audit(actor_id,action,subject_id,detail,created_at) VALUES(?,?,?,?,?)').run(actor||null,action,subject||null,String(detail).slice(0,1000),nowIso());}
function hasPermission(user,permission){return user?.role==='Owner'||(JSON.parse(user?.permissions||'[]').includes(permission));}
function publicUser(row,includePrivate=false){const salary=(row.salary_paise==null)?null:row.salary_paise/100;let upi='';if(row.salary_upi_enc){try{const value=decryptField(row);upi=value.length>5?value.slice(0,2)+'••••'+value.slice(value.indexOf('@')):'••••';}catch{upi='Unavailable';}}return {id:row.id,username:row.username,fullName:row.full_name,role:row.role,status:row.status,contact:row.contact,plan:row.plan,permissions:JSON.parse(row.permissions||'[]'),salary:includePrivate?salary:undefined,salaryUpiMasked:upi,salaryUpiConfirmed:Boolean(row.salary_upi_confirmed),joinedOn:row.joined_on,shift:row.shift,forcePasswordChange:Boolean(row.force_password_change)};}
function cookieValue(req){const line=req.headers.cookie||'';for(const part of line.split(';')){const [k,...v]=part.trim().split('=');if(k===cookieName)return decodeURIComponent(v.join('='));}return '';}
function setCookie(res,token){const secure=process.env.POS_COOKIE_SECURE==='1'?'; Secure':'';res.setHeader('Set-Cookie',`${cookieName}=${encodeURIComponent(token)}; HttpOnly; SameSite=Strict; Path=/; Max-Age=${SESSION_MS/1000}${secure}`);}
function clearCookie(res){res.setHeader('Set-Cookie',`${cookieName}=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0${process.env.POS_COOKIE_SECURE==='1'?'; Secure':''}`);}
function json(res,status,data){const body=JSON.stringify(data);res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','Content-Length':Buffer.byteLength(body)});res.end(body);}
async function readBody(req){let data='';for await(const chunk of req){data+=chunk;if(data.length>12*1024*1024)throw Object.assign(new Error('Request too large'),{status:413});}if(!data)return {};try{return JSON.parse(data);}catch{throw Object.assign(new Error('Invalid JSON'),{status:400});}}
function error(res,status,message){json(res,status,{error:message});}
function parseCookieSession(req){const token=cookieValue(req);if(!token)return null;return {token,hash:tokenHash(token)};}
function auth(req,res,{mutating=false,reauth=false,allowSetup=false}={}){const t=parseCookieSession(req);if(!t){error(res,401,'Sign in required');return null;}const row=database.prepare(`SELECT s.*,a.* FROM sessions s JOIN accounts a ON a.id=s.account_id WHERE s.token_hash=?`).get(t.hash);const now=Date.now();if(!row||row.expires_at<now||row.status!=='Active'){if(row)database.prepare('DELETE FROM sessions WHERE token_hash=?').run(t.hash);clearCookie(res);error(res,401,'Session expired. Sign in again.');return null;}if(mutating&&!safeEqual(req.headers['x-csrf-token']||'',row.csrf)){error(res,403,'Security token expired. Refresh and try again.');return null;}if(row.force_password_change&&!allowSetup){error(res,428,'First login setup must be completed');return null;}if(reauth&&row.reauth_until<now){error(res,403,'reauth_required');return null;}database.prepare('UPDATE sessions SET last_seen=?,expires_at=? WHERE token_hash=?').run(now,now+SESSION_MS,t.hash);return {row,tokenHash:t.hash};}
async function beginSession(res,user,force=false){const token=randomBytes(32).toString('base64url'),csrf=randomBytes(24).toString('base64url'),now=Date.now(),mustChangePassword=force||Boolean(user.force_password_change);database.prepare('INSERT INTO sessions(token_hash,account_id,csrf,created_at,last_seen,expires_at,reauth_until) VALUES(?,?,?,?,?,?,0)').run(tokenHash(token),user.id,csrf,now,now,now+SESSION_MS);setCookie(res,token);return {user:publicUser(user,true),csrf,mustChangePassword,ownerVerificationRequired:mustChangePassword&&user.role==='Owner'&&user.username===OWNER_USERNAME};}
function currentUser(req,res,options={}){return auth(req,res,options);}
function roleOrPermission(ctx,roles,permission){if(roles.includes(ctx.row.role))return true;if(permission&&hasPermission(ctx.row,permission))return true;return false;}
function requirePermission(ctx,res,permission){if(!hasPermission(ctx.row,permission)){error(res,403,'You do not have permission to perform this action');return false;}return true;}
function requireRole(ctx,res,...roles){if(!roles.includes(ctx.row.role)){error(res,403,'This page is not available for your account');return false;}return true;}
function needReauth(ctx,res){if(ctx.row.reauth_until<Date.now()){error(res,403,'reauth_required');return false;}return true;}
function maskContact(value){return value?`••••${value.replace(/\D/g,'').slice(-4)}`:'';}
function ownerApiInfo(user){return {user:{...publicUser(user,true),passwordChangedAt:user.password_changed_at||user.updated_at}};}
const catalogVersion=()=>Number(database.prepare("SELECT value FROM business_settings WHERE key='catalog_version'").get()?.value||1);
