function publicProduct(row){return {id:row.id,name:row.name,category:row.category,code:row.code,unit:row.unit,price:row.rate_paise==null?null:row.rate_paise/100,ratePaise:row.rate_paise,active:row.status==='Active',status:row.status,version:row.version,updatedAt:row.updated_at};}
function isPriceManager(user){return user?.role==='Owner'||hasPermission(user,'manage_product_prices');}
