function taxSettings(){const read=k=>database.prepare('SELECT value FROM business_settings WHERE key=?').get(k)?.value;return {rateBps:Math.max(0,Math.min(10000,Number(read('tax_rate_bps'))||0)),mode:read('tax_mode')==='interstate'?'interstate':'intrastate',inclusive:read('tax_inclusive')==='1'};}
