function publicTaxSettings(){const t=taxSettings();return {rateBps:t.rateBps,ratePercent:t.rateBps/100,mode:t.mode,inclusive:t.inclusive};}function dreamPayRead(key){return database.prepare('SELECT value FROM business_settings WHERE key=?').get('dream_pay_'+key)?.value||''}
